import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CegG7-6m.js";var i=JSON.parse(`{"title":"Tool reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1788701861000}`),a={name:`reference/tools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="tool-reference" tabindex="-1">Tool reference <a class="header-anchor" href="#tool-reference" aria-label="Permalink to “Tool reference”">​</a></h1><p>All 22 tools: 10 read, 12 write. With <code>CALDAV_READ_ONLY=true</code> the write tools are not registered at all — they do not appear in <code>tools/list</code>.</p><p>All 22 are registered unless you say otherwise. <code>CALDAV_ALLOW_TOOLS</code> and <code>CALDAV_DENY_TOOLS</code> narrow the list to the ones you want, and <code>CALDAV_ALLOW_TOOLS=essential</code> selects the 7 marked <strong>essential</strong> below — see <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><p>👤 marks a tool that <strong>asks a person</strong> before it acts, through MCP elicitation — a dialog the model cannot answer on its behalf. Where the client cannot show one, it falls back to a two-call <code>confirm_token</code> bound to the exact target and expiring after five minutes, and says which of the two it was. <code>ELICITATION=false</code> takes that fallback deliberately; it never removes the guard. See <a href="/guide/approval">Asking a person</a>.</p><p>Every tool declares all four MCP annotations — <code>readOnlyHint</code>, <code>destructiveHint</code>, <code>idempotentHint</code>, <code>openWorldHint</code>. They are a hint a client may ignore; the dialog is enforced here and cannot be, which is why the two lists are not the same one.</p><h2 id="read-tools" tabindex="-1">Read tools <a class="header-anchor" href="#read-tools" aria-label="Permalink to “Read tools”">​</a></h2><h3 id="list-calendars" tabindex="-1"><code>list_calendars</code> <a class="header-anchor" href="#list-calendars" aria-label="Permalink to “list_calendars”">​</a></h3><p><strong>List the calendars</strong> — read-only, <strong>essential</strong></p><p>Every calendar this server may use, with the id to pass to the other tools. Always asks the server rather than answering from a cache — being current is this tool’s whole job.</p><p>Takes no parameters.</p><h3 id="get-server-info" tabindex="-1"><code>get_server_info</code> <a class="header-anchor" href="#get-server-info" aria-label="Permalink to “get_server_info”">​</a></h3><p><strong>What the connected CalDAV server can do</strong> — read-only</p><p>Reports the DAV compliance tokens, which components each calendar accepts, and whether the optional features this server relies on actually work here. The first thing to run when something behaves differently than expected — CalDAV implementations differ more than the specification suggests.</p><p>Takes no parameters.</p><h3 id="list-events" tabindex="-1"><code>list_events</code> <a class="header-anchor" href="#list-events" aria-label="Permalink to “list_events”">​</a></h3><p><strong>List events in a time range</strong> — read-only, <strong>essential</strong></p><p>Events between two points in time, from every calendar this server may see or from the ones named. Recurring events are expanded into their individual occurrences, so each one has its own id and can be changed on its own. Defaults to the next 30 days.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>from</code></td><td>string</td><td>no</td><td>Start of the window. Defaults to now.</td></tr><tr><td><code>to</code></td><td>string</td><td>no</td><td>End of the window. Defaults to 30 days after <code>from</code>.</td></tr><tr><td><code>timezone</code></td><td>string</td><td>no</td><td>IANA zone for timestamps that carry no offset, e.g. &quot;Europe/Berlin&quot;. Defaults to CALDAV_TIMEZONE. Refused together with a value that already carries an offset.</td></tr><tr><td><code>calendars</code></td><td>string[]</td><td>no</td><td>Which calendars to look in. Leave it out for all of them. A calendar outside CALDAV_CALENDARS is refused rather than silently skipped.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>Entries to return, at most 500. Defaults to CALDAV_MAX_EVENTS.</td></tr><tr><td><code>after</code></td><td>string</td><td>no</td><td>The <code>truncated.next_cursor</code> of a previous call, to continue where it stopped. The window has to be the same one.</td></tr></tbody></table><h3 id="get-event" tabindex="-1"><code>get_event</code> <a class="header-anchor" href="#get-event" aria-label="Permalink to “get_event”">​</a></h3><p><strong>Read one event in full</strong> — read-only, <strong>essential</strong></p><p>The complete event behind an id from a listing: the untruncated description, every reminder, every attendee, every attachment as metadata. An occurrence id answers with that one instance; a series id answers with the series and its rule.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from a listing tool. Not meant to be built by hand.</td></tr></tbody></table><h3 id="search-events" tabindex="-1"><code>search_events</code> <a class="header-anchor" href="#search-events" aria-label="Permalink to “search_events”">​</a></h3><p><strong>Search events by text</strong> — read-only, <strong>essential</strong></p><p>Finds events whose summary, description or location contains a term. The search runs on the CalDAV server, one request per field and per calendar — the specification combines several field filters with AND, so asking for all three at once would only match entries carrying the term in every one of them.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>yes</td><td>The term to look for. Matching is the server’s to define.</td></tr><tr><td><code>fields</code></td><td><code>&quot;SUMMARY&quot;</code> | <code>&quot;DESCRIPTION&quot;</code> | <code>&quot;LOCATION&quot;</code>[]</td><td>no</td><td>Which fields to search. Defaults to all three.</td></tr><tr><td><code>from</code></td><td>string</td><td>no</td><td>ISO 8601: &quot;2026-09-07&quot; for a whole day, &quot;2026-09-07T09:00:00&quot; in the timezone argument or CALDAV_TIMEZONE, or &quot;2026-09-07T09:00:00+02:00&quot;.</td></tr><tr><td><code>to</code></td><td>string</td><td>no</td><td>ISO 8601: &quot;2026-09-07&quot; for a whole day, &quot;2026-09-07T09:00:00&quot; in the timezone argument or CALDAV_TIMEZONE, or &quot;2026-09-07T09:00:00+02:00&quot;.</td></tr><tr><td><code>timezone</code></td><td>string</td><td>no</td><td>IANA zone for timestamps that carry no offset, e.g. &quot;Europe/Berlin&quot;. Defaults to CALDAV_TIMEZONE. Refused together with a value that already carries an offset.</td></tr><tr><td><code>calendars</code></td><td>string[]</td><td>no</td><td>Which calendars to look in. Leave it out for all of them. A calendar outside CALDAV_CALENDARS is refused rather than silently skipped.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>Entries to return, at most 500. Defaults to CALDAV_MAX_EVENTS.</td></tr></tbody></table><h3 id="get-free-busy" tabindex="-1"><code>get_free_busy</code> <a class="header-anchor" href="#get-free-busy" aria-label="Permalink to “get_free_busy”">​</a></h3><p><strong>When the calendar is busy</strong> — read-only, <strong>essential</strong></p><p>Busy periods in a time range — start and end only, no titles and no attendees. The datasparing way to ask &quot;when am I free&quot;: nothing anybody else wrote comes back, so there is no untrusted content in the answer at all.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>from</code></td><td>string</td><td>no</td><td>ISO 8601: &quot;2026-09-07&quot; for a whole day, &quot;2026-09-07T09:00:00&quot; in the timezone argument or CALDAV_TIMEZONE, or &quot;2026-09-07T09:00:00+02:00&quot;.</td></tr><tr><td><code>to</code></td><td>string</td><td>no</td><td>ISO 8601: &quot;2026-09-07&quot; for a whole day, &quot;2026-09-07T09:00:00&quot; in the timezone argument or CALDAV_TIMEZONE, or &quot;2026-09-07T09:00:00+02:00&quot;.</td></tr><tr><td><code>timezone</code></td><td>string</td><td>no</td><td>IANA zone for timestamps that carry no offset, e.g. &quot;Europe/Berlin&quot;. Defaults to CALDAV_TIMEZONE. Refused together with a value that already carries an offset.</td></tr><tr><td><code>calendars</code></td><td>string[]</td><td>no</td><td>Which calendars to look in. Leave it out for all of them. A calendar outside CALDAV_CALENDARS is refused rather than silently skipped.</td></tr></tbody></table><h3 id="list-tasks" tabindex="-1"><code>list_tasks</code> <a class="header-anchor" href="#list-tasks" aria-label="Permalink to “list_tasks”">​</a></h3><p><strong>List tasks</strong> — read-only</p><p>Tasks with a start or due date inside a time range. Tasks with no date at all are not returned by a time-range query — the CalDAV specification defines the filter against the dates, and a task with none of them matches no window.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>from</code></td><td>string</td><td>no</td><td>ISO 8601: &quot;2026-09-07&quot; for a whole day, &quot;2026-09-07T09:00:00&quot; in the timezone argument or CALDAV_TIMEZONE, or &quot;2026-09-07T09:00:00+02:00&quot;.</td></tr><tr><td><code>to</code></td><td>string</td><td>no</td><td>ISO 8601: &quot;2026-09-07&quot; for a whole day, &quot;2026-09-07T09:00:00&quot; in the timezone argument or CALDAV_TIMEZONE, or &quot;2026-09-07T09:00:00+02:00&quot;.</td></tr><tr><td><code>timezone</code></td><td>string</td><td>no</td><td>IANA zone for timestamps that carry no offset, e.g. &quot;Europe/Berlin&quot;. Defaults to CALDAV_TIMEZONE. Refused together with a value that already carries an offset.</td></tr><tr><td><code>calendars</code></td><td>string[]</td><td>no</td><td>Which calendars to look in. Leave it out for all of them. A calendar outside CALDAV_CALENDARS is refused rather than silently skipped.</td></tr><tr><td><code>include_completed</code></td><td>boolean</td><td>no</td><td>Defaults to false, which leaves completed tasks out.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>Entries to return, at most 500. Defaults to CALDAV_MAX_EVENTS.</td></tr><tr><td><code>after</code></td><td>string</td><td>no</td><td>The <code>truncated.next_cursor</code> of a previous call, to continue where it stopped. The window has to be the same one.</td></tr></tbody></table><h3 id="get-task" tabindex="-1"><code>get_task</code> <a class="header-anchor" href="#get-task" aria-label="Permalink to “get_task”">​</a></h3><p><strong>Read one task in full</strong> — read-only</p><p>The complete task behind an id from list_tasks, with its untruncated description and every reminder.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from a listing tool. Not meant to be built by hand.</td></tr></tbody></table><h3 id="list-journals" tabindex="-1"><code>list_journals</code> <a class="header-anchor" href="#list-journals" aria-label="Permalink to “list_journals”">​</a></h3><p><strong>List journal entries</strong> — read-only</p><p>Dated notes in a calendar, inside a time range. Most calendar clients hide these; a CalDAV server stores them alongside events and tasks, and some workflows use them as a diary.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>from</code></td><td>string</td><td>no</td><td>ISO 8601: &quot;2026-09-07&quot; for a whole day, &quot;2026-09-07T09:00:00&quot; in the timezone argument or CALDAV_TIMEZONE, or &quot;2026-09-07T09:00:00+02:00&quot;.</td></tr><tr><td><code>to</code></td><td>string</td><td>no</td><td>ISO 8601: &quot;2026-09-07&quot; for a whole day, &quot;2026-09-07T09:00:00&quot; in the timezone argument or CALDAV_TIMEZONE, or &quot;2026-09-07T09:00:00+02:00&quot;.</td></tr><tr><td><code>timezone</code></td><td>string</td><td>no</td><td>IANA zone for timestamps that carry no offset, e.g. &quot;Europe/Berlin&quot;. Defaults to CALDAV_TIMEZONE. Refused together with a value that already carries an offset.</td></tr><tr><td><code>calendars</code></td><td>string[]</td><td>no</td><td>Which calendars to look in. Leave it out for all of them. A calendar outside CALDAV_CALENDARS is refused rather than silently skipped.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>Entries to return, at most 500. Defaults to CALDAV_MAX_EVENTS.</td></tr><tr><td><code>after</code></td><td>string</td><td>no</td><td>The <code>truncated.next_cursor</code> of a previous call, to continue where it stopped. The window has to be the same one.</td></tr></tbody></table><h3 id="get-journal" tabindex="-1"><code>get_journal</code> <a class="header-anchor" href="#get-journal" aria-label="Permalink to “get_journal”">​</a></h3><p><strong>Read one journal entry in full</strong> — read-only</p><p>The complete note behind an id from list_journals, untruncated. This is the longest piece of somebody else’s prose this server hands over, so the text channel carries it inside an explicit untrusted fence.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from a listing tool. Not meant to be built by hand.</td></tr></tbody></table><h2 id="write-tools" tabindex="-1">Write tools <a class="header-anchor" href="#write-tools" aria-label="Permalink to “Write tools”">​</a></h2><h3 id="create-event" tabindex="-1"><code>create_event</code> <a class="header-anchor" href="#create-event" aria-label="Permalink to “create_event”">​</a></h3><p><strong>Create an event</strong> — write, <strong>essential</strong></p><p>Adds an event to a calendar. The UID and the file name are generated here, so an existing entry can never be overwritten by accident. Times without an offset are read in the timezone argument or in CALDAV_TIMEZONE.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>calendar_id</code></td><td>string</td><td>yes</td><td>A calendar id from list_calendars — its path. A full URL or the final path segment work too.</td></tr><tr><td><code>summary</code></td><td>string</td><td>yes</td><td>The title.</td></tr><tr><td><code>start</code></td><td>string</td><td>yes</td><td>When it starts. A bare date makes it an all-day event.</td></tr><tr><td><code>end</code></td><td>string</td><td>no</td><td>When it ends. For an all-day event this is exclusive, as iCalendar defines it: a single day ends on the following date. Defaults to one hour after the start, or one day for an all-day event.</td></tr><tr><td><code>timezone</code></td><td>string</td><td>no</td><td>IANA zone for timestamps that carry no offset, e.g. &quot;Europe/Berlin&quot;. Defaults to CALDAV_TIMEZONE. Refused together with a value that already carries an offset.</td></tr><tr><td><code>description</code></td><td>unknown</td><td>no</td><td>Longer text. Pass null to remove it, leave it out to keep it.</td></tr><tr><td><code>location</code></td><td>unknown</td><td>no</td><td>Where it happens. Pass null to remove it, leave it out to keep it.</td></tr><tr><td><code>categories</code></td><td>unknown</td><td>no</td><td>Replaces every category. Pass null or an empty array to clear.</td></tr><tr><td><code>status</code></td><td><code>&quot;CONFIRMED&quot;</code> | <code>&quot;TENTATIVE&quot;</code> | <code>&quot;CANCELLED&quot;</code></td><td>no</td><td></td></tr><tr><td><code>transparent</code></td><td>boolean</td><td>no</td><td>True to leave the time free rather than marking it busy.</td></tr><tr><td><code>recurrence</code></td><td>string</td><td>no</td><td>A raw RRULE, e.g. &quot;FREQ=WEEKLY;BYDAY=MO;COUNT=10&quot;. Given as written rather than as separate fields, because the rule grammar is richer than any short set of parameters, and a half-modelled rule is how a series ends up wrong.</td></tr><tr><td><code>alarms</code></td><td>object[]</td><td>no</td><td>Replaces the plain DISPLAY reminders. An empty array removes them. Reminders this server cannot write — email alarms, repeating ones, ones with an attachment — are always kept, and the answer says how many.</td></tr></tbody></table><h3 id="update-event-👤" tabindex="-1"><code>update_event</code> 👤 <a class="header-anchor" href="#update-event-👤" aria-label="Permalink to “update_event 👤”">​</a></h3><p><strong>Change an event</strong> — write, destructive, <strong>essential</strong></p><p>Changes the fields named and leaves everything else exactly as it was — including properties this server does not model, attendees, attachments and reminders it cannot write. Pass null to clear a field. Guarded by the entry’s ETag: if it changed since it was read, nothing is written and the answer says what it is now. Changing a whole recurring series asks first.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from a listing tool. Not meant to be built by hand.</td></tr><tr><td><code>scope</code></td><td><code>&quot;this_occurrence&quot;</code> | <code>&quot;entire_series&quot;</code></td><td>no</td><td>For a recurring entry: change just this occurrence, or the whole series. Defaults to whichever the id names. Changing a whole series asks first.</td></tr><tr><td><code>summary</code></td><td>string</td><td>no</td><td>The title.</td></tr><tr><td><code>start</code></td><td>string</td><td>no</td><td>ISO 8601: &quot;2026-09-07&quot; for a whole day, &quot;2026-09-07T09:00:00&quot; in the timezone argument or CALDAV_TIMEZONE, or &quot;2026-09-07T09:00:00+02:00&quot;.</td></tr><tr><td><code>end</code></td><td>string</td><td>no</td><td>ISO 8601: &quot;2026-09-07&quot; for a whole day, &quot;2026-09-07T09:00:00&quot; in the timezone argument or CALDAV_TIMEZONE, or &quot;2026-09-07T09:00:00+02:00&quot;.</td></tr><tr><td><code>timezone</code></td><td>string</td><td>no</td><td>IANA zone for timestamps that carry no offset, e.g. &quot;Europe/Berlin&quot;. Defaults to CALDAV_TIMEZONE. Refused together with a value that already carries an offset.</td></tr><tr><td><code>description</code></td><td>unknown</td><td>no</td><td>Longer text. Pass null to remove it, leave it out to keep it.</td></tr><tr><td><code>location</code></td><td>unknown</td><td>no</td><td>Where it happens. Pass null to remove it, leave it out to keep it.</td></tr><tr><td><code>categories</code></td><td>unknown</td><td>no</td><td>Replaces every category. Pass null or an empty array to clear.</td></tr><tr><td><code>status</code></td><td><code>&quot;CONFIRMED&quot;</code> | <code>&quot;TENTATIVE&quot;</code> | <code>&quot;CANCELLED&quot;</code></td><td>no</td><td></td></tr><tr><td><code>transparent</code></td><td>boolean</td><td>no</td><td></td></tr><tr><td><code>alarms</code></td><td>object[]</td><td>no</td><td>Replaces the plain DISPLAY reminders. An empty array removes them. Reminders this server cannot write — email alarms, repeating ones, ones with an attachment — are always kept, and the answer says how many.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from the first call of this tool.</td></tr></tbody></table><h3 id="delete-event-👤" tabindex="-1"><code>delete_event</code> 👤 <a class="header-anchor" href="#delete-event-👤" aria-label="Permalink to “delete_event 👤”">​</a></h3><p><strong>Delete an event</strong> — write, destructive</p><p>Removes an event. An occurrence id removes just that occurrence — which iCalendar does by adding an exception date to the series, so the rest of the series is untouched. A series id removes the whole entry. A CalDAV server keeps no history: this cannot be undone.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from a listing tool. Not meant to be built by hand.</td></tr><tr><td><code>scope</code></td><td><code>&quot;this_occurrence&quot;</code> | <code>&quot;entire_series&quot;</code></td><td>no</td><td>For a recurring entry: change just this occurrence, or the whole series. Defaults to whichever the id names. Changing a whole series asks first.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from the first call of this tool.</td></tr></tbody></table><h3 id="move-event-👤" tabindex="-1"><code>move_event</code> 👤 <a class="header-anchor" href="#move-event-👤" aria-label="Permalink to “move_event 👤”">​</a></h3><p><strong>Move an event to another calendar</strong> — write, destructive</p><p>Copies an event into another calendar and removes it from the first. The content survives, the address does not: every id that named this event stops working, and a listing is needed to get the new one. The destination may be a calendar other people can see.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from a listing tool. Not meant to be built by hand.</td></tr><tr><td><code>destination_calendar_id</code></td><td>string</td><td>yes</td><td>A calendar id from list_calendars — its path. A full URL or the final path segment work too.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from the first call of this tool.</td></tr></tbody></table><h3 id="respond-to-event-👤" tabindex="-1"><code>respond_to_event</code> 👤 <a class="header-anchor" href="#respond-to-event-👤" aria-label="Permalink to “respond_to_event 👤”">​</a></h3><p><strong>Accept or decline an invitation</strong> — write</p><p>Sets your own participation status on an event you were invited to. On a server with scheduling enabled this sends a reply to the organiser, which cannot be unsent — so it asks first. It changes only your own attendee line and never anybody else’s. This server cannot add or remove attendees at all.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from a listing tool. Not meant to be built by hand.</td></tr><tr><td><code>response</code></td><td><code>&quot;ACCEPTED&quot;</code> | <code>&quot;DECLINED&quot;</code> | <code>&quot;TENTATIVE&quot;</code></td><td>yes</td><td>Your answer.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from the first call of this tool.</td></tr></tbody></table><h3 id="create-task" tabindex="-1"><code>create_task</code> <a class="header-anchor" href="#create-task" aria-label="Permalink to “create_task”">​</a></h3><p><strong>Create a task</strong> — write</p><p>Adds a task to a calendar that accepts them. list_calendars reports which do — a collection created for events only will refuse a task, and this server checks before writing rather than passing the server’s refusal back.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>calendar_id</code></td><td>string</td><td>yes</td><td>A calendar id from list_calendars — its path. A full URL or the final path segment work too.</td></tr><tr><td><code>summary</code></td><td>string</td><td>yes</td><td>The title.</td></tr><tr><td><code>due</code></td><td>string</td><td>no</td><td>When it is due.</td></tr><tr><td><code>start</code></td><td>string</td><td>no</td><td>When work on it can begin.</td></tr><tr><td><code>timezone</code></td><td>string</td><td>no</td><td>IANA zone for timestamps that carry no offset, e.g. &quot;Europe/Berlin&quot;. Defaults to CALDAV_TIMEZONE. Refused together with a value that already carries an offset.</td></tr><tr><td><code>description</code></td><td>unknown</td><td>no</td><td>Longer text. Pass null to remove it, leave it out to keep it.</td></tr><tr><td><code>priority</code></td><td>integer</td><td>no</td><td>1 is highest, 9 lowest, 0 undefined — as RFC 5545 has it.</td></tr><tr><td><code>categories</code></td><td>unknown</td><td>no</td><td>Replaces every category. Pass null or an empty array to clear.</td></tr><tr><td><code>alarms</code></td><td>object[]</td><td>no</td><td>Replaces the plain DISPLAY reminders. An empty array removes them. Reminders this server cannot write — email alarms, repeating ones, ones with an attachment — are always kept, and the answer says how many.</td></tr></tbody></table><h3 id="update-task" tabindex="-1"><code>update_task</code> <a class="header-anchor" href="#update-task" aria-label="Permalink to “update_task”">​</a></h3><p><strong>Change a task</strong> — write, destructive</p><p>Changes the fields named and leaves everything else as it was. Pass null to clear a field. Guarded by the entry’s ETag. To mark a task done use complete_task, which records the completion time as well.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from a listing tool. Not meant to be built by hand.</td></tr><tr><td><code>summary</code></td><td>string</td><td>no</td><td>The title.</td></tr><tr><td><code>due</code></td><td>string</td><td>no</td><td>ISO 8601: &quot;2026-09-07&quot; for a whole day, &quot;2026-09-07T09:00:00&quot; in the timezone argument or CALDAV_TIMEZONE, or &quot;2026-09-07T09:00:00+02:00&quot;.</td></tr><tr><td><code>start</code></td><td>string</td><td>no</td><td>ISO 8601: &quot;2026-09-07&quot; for a whole day, &quot;2026-09-07T09:00:00&quot; in the timezone argument or CALDAV_TIMEZONE, or &quot;2026-09-07T09:00:00+02:00&quot;.</td></tr><tr><td><code>timezone</code></td><td>string</td><td>no</td><td>IANA zone for timestamps that carry no offset, e.g. &quot;Europe/Berlin&quot;. Defaults to CALDAV_TIMEZONE. Refused together with a value that already carries an offset.</td></tr><tr><td><code>description</code></td><td>unknown</td><td>no</td><td>Longer text. Pass null to remove it, leave it out to keep it.</td></tr><tr><td><code>priority</code></td><td>integer</td><td>no</td><td></td></tr><tr><td><code>percent_complete</code></td><td>integer</td><td>no</td><td></td></tr><tr><td><code>categories</code></td><td>unknown</td><td>no</td><td>Replaces every category. Pass null or an empty array to clear.</td></tr><tr><td><code>alarms</code></td><td>object[]</td><td>no</td><td>Replaces the plain DISPLAY reminders. An empty array removes them. Reminders this server cannot write — email alarms, repeating ones, ones with an attachment — are always kept, and the answer says how many.</td></tr></tbody></table><h3 id="complete-task" tabindex="-1"><code>complete_task</code> <a class="header-anchor" href="#complete-task" aria-label="Permalink to “complete_task”">​</a></h3><p><strong>Mark a task done, or reopen it</strong> — write</p><p>Sets the task’s status. Marking it done records the completion time and sets it to 100 %; reopening clears both. The previous state is written down in the entry, so this is reversible — which is why it does not ask first.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from a listing tool. Not meant to be built by hand.</td></tr><tr><td><code>done</code></td><td>boolean</td><td>no</td><td>Defaults to true. Pass false to reopen a completed task.</td></tr></tbody></table><h3 id="delete-task-👤" tabindex="-1"><code>delete_task</code> 👤 <a class="header-anchor" href="#delete-task-👤" aria-label="Permalink to “delete_task 👤”">​</a></h3><p><strong>Delete a task</strong> — write, destructive</p><p>Removes a task. A CalDAV server keeps no history: this cannot be undone. To mark a task done instead, use complete_task.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from a listing tool. Not meant to be built by hand.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from the first call of this tool.</td></tr></tbody></table><h3 id="create-journal" tabindex="-1"><code>create_journal</code> <a class="header-anchor" href="#create-journal" aria-label="Permalink to “create_journal”">​</a></h3><p><strong>Create a journal entry</strong> — write</p><p>Adds a dated note to a calendar that accepts journal entries. list_calendars reports which do.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>calendar_id</code></td><td>string</td><td>yes</td><td>A calendar id from list_calendars — its path. A full URL or the final path segment work too.</td></tr><tr><td><code>summary</code></td><td>string</td><td>yes</td><td>The heading.</td></tr><tr><td><code>date</code></td><td>string</td><td>yes</td><td>The date the note belongs to.</td></tr><tr><td><code>timezone</code></td><td>string</td><td>no</td><td>IANA zone for timestamps that carry no offset, e.g. &quot;Europe/Berlin&quot;. Defaults to CALDAV_TIMEZONE. Refused together with a value that already carries an offset.</td></tr><tr><td><code>description</code></td><td>unknown</td><td>no</td><td>The note itself. Pass null to remove it, leave it out to keep it.</td></tr><tr><td><code>categories</code></td><td>unknown</td><td>no</td><td>Replaces every category. Pass null or an empty array to clear.</td></tr></tbody></table><h3 id="update-journal" tabindex="-1"><code>update_journal</code> <a class="header-anchor" href="#update-journal" aria-label="Permalink to “update_journal”">​</a></h3><p><strong>Change a journal entry</strong> — write, destructive</p><p>Replaces the fields named. A CalDAV server keeps no version history, so the previous text of a note is gone once this succeeds — pass only the fields to change, and pass null to clear one. Guarded by the entry’s ETag, so a note changed elsewhere in the meantime is not silently overwritten.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from a listing tool. Not meant to be built by hand.</td></tr><tr><td><code>summary</code></td><td>string</td><td>no</td><td>The title.</td></tr><tr><td><code>date</code></td><td>string</td><td>no</td><td>ISO 8601: &quot;2026-09-07&quot; for a whole day, &quot;2026-09-07T09:00:00&quot; in the timezone argument or CALDAV_TIMEZONE, or &quot;2026-09-07T09:00:00+02:00&quot;.</td></tr><tr><td><code>timezone</code></td><td>string</td><td>no</td><td>IANA zone for timestamps that carry no offset, e.g. &quot;Europe/Berlin&quot;. Defaults to CALDAV_TIMEZONE. Refused together with a value that already carries an offset.</td></tr><tr><td><code>description</code></td><td>unknown</td><td>no</td><td>The note itself. Pass null to remove it, leave it out to keep it.</td></tr><tr><td><code>categories</code></td><td>unknown</td><td>no</td><td>Replaces every category. Pass null or an empty array to clear.</td></tr></tbody></table><h3 id="delete-journal-👤" tabindex="-1"><code>delete_journal</code> 👤 <a class="header-anchor" href="#delete-journal-👤" aria-label="Permalink to “delete_journal 👤”">​</a></h3><p><strong>Delete a journal entry</strong> — write, destructive</p><p>Removes a dated note. A CalDAV server keeps no history, and a note is somebody’s writing: this cannot be undone.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from a listing tool. Not meant to be built by hand.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from the first call of this tool.</td></tr></tbody></table>`,95)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};